CREATE TABLE hits (watch_id Int64, event_time DateTime64(6), event_date Date, counter_id Int32, client_ip Int32, region_id Int32, user_id Int64, os Int16, user_agent Int16, url String, referer String, is_refresh Int16, resolution_width Int16, mobile_phone_model String, search_phrase String, adv_engine_id Int16) ENGINE = MergeTree ORDER BY (counter_id, event_date, user_id, event_time, watch_id)
